INSERT INTO `ldcrm_tpm_customreport` (`report_id`, `report_name`, `report_desc`, `report_type`, `parent_id`, `sequence`, `mainmodule`, `createdtime`, `modify_time`, `deleted`, `modify_id`, `limit`, `orderby`, `orderby_type`, `smcreatorid`, `stat_approach`, `approveallocatetype`, `show_athome`, `linkmodulecheck`, `can_penetrate`, `relatedmodule`, `isshow_search`, `isshow_table`, `analysisfolder_id`, `sqlstr`, `themename`, `advance_demand`, `advance_demand_groups`, `primaryname`) VALUES ('279', '产品签约数量同比', '', 'sqlchart', @parent_id, '0', NULL, '2023-11-22 16:31:40', '2023-11-28 19:17:21', '0', '1', NULL, NULL, NULL, '1', NULL, '0', 'yes', 'no', 'no', NULL, 'yes', 'Bottom', '1', 'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	sum(p_num.pre_num) AS pre_num,\n	sum(p_num.now_num) AS now_num\nFROM\n	(\n		(\n			SELECT\n				timetype_table.where_time AS where_time,\n				timetype_table.group_time AS group_time,\n				pre_salesorder.salesorderid AS pre_id,\n				pre_salesorder.quantity AS pre_num,\n				now_salesorder.salesorderid AS now_id,\n				now_salesorder.quantity AS now_num\n			FROM\n				(\n					SELECT\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (NOW())\n							ELSE\n								YEAR (NOW())\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (date)\n							ELSE\n								MONTH (date)\n							END\n						) AS group_time\n					FROM\n						tmp_date a\n					WHERE\n						date LIKE \'%2023%\'\n					GROUP BY\n						group_time\n				) timetype_table\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						ELSE\n							YEAR (ld_salesorder.signed_data)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(now_s_detail.quantity) AS quantity\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				AND (\n					ld_salesorder.signed_data BETWEEN \'{starttime}\'\n					AND \'{endtime}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n			AND now_salesorder.group_time = timetype_table.group_time\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(pre_s_detail.quantity) AS quantity\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n			AND pre_salesorder.group_time = timetype_table.group_time\n			GROUP BY\n				timetype_table.group_time\n		)\n		UNION ALL\n			(\n				SELECT\n					timetype_table.where_time AS where_time,\n					timetype_table.group_time AS group_time,\n					pre_servicecontracts.servicecontractsid AS pre_id,\n					pre_servicecontracts.quantity AS pre_num,\n					now_servicecontracts.servicecontractsid AS now_id,\n					now_servicecontracts.quantity AS now_num\n				FROM\n					(\n						SELECT\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									QUARTER (NOW())\n								ELSE\n									YEAR (NOW())\n								END\n							) AS where_time,\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									MONTH (date)\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									QUARTER (date)\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									MONTH (date)\n								ELSE\n									MONTH (date)\n								END\n							) AS group_time\n						FROM\n							tmp_date a\n						WHERE\n							date LIKE \'%2023%\'\n						GROUP BY\n							group_time\n					) timetype_table\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (due_date)\n							ELSE\n								YEAR (due_date)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (due_date)\n							ELSE\n								MONTH (due_date)\n							END\n						) AS group_time,\n						sum(now_sv_detail.quantity) AS quantity\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail now_sv_detail ON now_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = now_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					AND (\n						ld_servicecontracts.due_date BETWEEN \'{starttime}\'\n						AND \'{endtime}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) now_servicecontracts ON now_servicecontracts.where_time = timetype_table.where_time\n				AND now_servicecontracts.group_time = timetype_table.group_time\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 QUARTER\n									)\n								)\n							ELSE\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (\n									ld_servicecontracts.due_date\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							ELSE\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							END\n						) AS group_time,\n						sum(pre_sv_detail.quantity) AS quantity\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail pre_sv_detail ON pre_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = pre_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) pre_servicecontracts ON pre_servicecontracts.where_time = timetype_table.where_time\n				AND pre_servicecontracts.group_time = timetype_table.group_time\n				GROUP BY\n					timetype_table.group_time\n			)\n	) p_num\nGROUP BY\n	p_num.group_time', 'Default', NULL, NULL, 'product_contracted_quantity_y_to_y');
INSERT INTO `ldcrm_tpm_customreport` (`report_id`, `report_name`, `report_desc`, `report_type`, `parent_id`, `sequence`, `mainmodule`, `createdtime`, `modify_time`, `deleted`, `modify_id`, `limit`, `orderby`, `orderby_type`, `smcreatorid`, `stat_approach`, `approveallocatetype`, `show_athome`, `linkmodulecheck`, `can_penetrate`, `relatedmodule`, `isshow_search`, `isshow_table`, `analysisfolder_id`, `sqlstr`, `themename`, `advance_demand`, `advance_demand_groups`, `primaryname`) VALUES ('281', '产品签约金额同比', '', 'sqlchart', @parent_id, '0', NULL, '2023-11-23 16:07:10', '2023-11-28 16:24:14', '0', '1', NULL, NULL, NULL, '1', NULL, '0', 'yes', 'no', 'no', NULL, 'yes', 'Bottom', '1', 'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	sum(p_num.pre_tax_amount) AS pre_tax_amount,\n	sum(p_num.now_tax_amount) AS now_tax_amount\nFROM\n	(\n		(\n			SELECT\n				timetype_table.where_time AS where_time,\n				timetype_table.group_time AS group_time,\n				pre_salesorder.salesorderid AS pre_id,\n				pre_salesorder.tax_amount AS pre_tax_amount,\n				now_salesorder.salesorderid AS now_id,\n				now_salesorder.tax_amount AS now_tax_amount\n			FROM\n				(\n					SELECT\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (NOW())\n							ELSE\n								YEAR (NOW())\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (date)\n							ELSE\n								MONTH (date)\n							END\n						) AS group_time\n					FROM\n						tmp_date a\n					WHERE\n						date LIKE \'%2023%\'\n					GROUP BY\n						group_time\n				) timetype_table\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						ELSE\n							YEAR (ld_salesorder.signed_data)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(now_s_detail.tax_amount) AS tax_amount\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				AND (\n					ld_salesorder.signed_data BETWEEN \'{starttime}\'\n					AND \'{endtime}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n			AND now_salesorder.group_time = timetype_table.group_time\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(pre_s_detail.tax_amount) AS tax_amount\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n			AND pre_salesorder.group_time = timetype_table.group_time\n			GROUP BY\n				timetype_table.group_time\n		)\n		UNION ALL\n			(\n				SELECT\n					timetype_table.where_time AS where_time,\n					timetype_table.group_time AS group_time,\n					pre_servicecontracts.servicecontractsid AS pre_id,\n					pre_servicecontracts.tax_amount AS pre_tax_amount,\n					now_servicecontracts.servicecontractsid AS now_id,\n					now_servicecontracts.tax_amount AS now_tax_amount\n				FROM\n					(\n						SELECT\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									QUARTER (NOW())\n								ELSE\n									YEAR (NOW())\n								END\n							) AS where_time,\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									MONTH (date)\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									QUARTER (date)\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									MONTH (date)\n								ELSE\n									MONTH (date)\n								END\n							) AS group_time\n						FROM\n							tmp_date a\n						WHERE\n							date LIKE \'%2023%\'\n						GROUP BY\n							group_time\n					) timetype_table\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (due_date)\n							ELSE\n								YEAR (due_date)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (due_date)\n							ELSE\n								MONTH (due_date)\n							END\n						) AS group_time,\n						sum(now_sv_detail.tax_amount) AS tax_amount\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail now_sv_detail ON now_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = now_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					AND (\n						ld_servicecontracts.due_date BETWEEN \'{starttime}\'\n						AND \'{endtime}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) now_servicecontracts ON now_servicecontracts.where_time = timetype_table.where_time\n				AND now_servicecontracts.group_time = timetype_table.group_time\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 QUARTER\n									)\n								)\n							ELSE\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (\n									ld_servicecontracts.due_date\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							ELSE\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							END\n						) AS group_time,\n						sum(pre_sv_detail.tax_amount) AS tax_amount\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail pre_sv_detail ON pre_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = pre_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) pre_servicecontracts ON pre_servicecontracts.where_time = timetype_table.where_time\n				AND pre_servicecontracts.group_time = timetype_table.group_time\n				GROUP BY\n					timetype_table.group_time\n			)\n	) p_num\nGROUP BY\n	p_num.group_time', 'Default', NULL, NULL, 'product_contracted_amount_y_to_y');
INSERT INTO `ldcrm_tpm_customreport` (`report_id`, `report_name`, `report_desc`, `report_type`, `parent_id`, `sequence`, `mainmodule`, `createdtime`, `modify_time`, `deleted`, `modify_id`, `limit`, `orderby`, `orderby_type`, `smcreatorid`, `stat_approach`, `approveallocatetype`, `show_athome`, `linkmodulecheck`, `can_penetrate`, `relatedmodule`, `isshow_search`, `isshow_table`, `analysisfolder_id`, `sqlstr`, `themename`, `advance_demand`, `advance_demand_groups`, `primaryname`) VALUES ('282', '产品订单数量同比', '', 'sqlchart', @parent_id, '0', NULL, '2023-11-23 16:16:37', '2023-11-23 20:18:58', '0', '1', NULL, NULL, NULL, '1', NULL, '0', 'yes', 'no', 'no', NULL, 'yes', 'Bottom', '1', 'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	p_num.pre_num,\n	p_num.now_num\nFROM\n	(\n		SELECT\n			timetype_table.where_time AS where_time,\n			timetype_table.group_time AS group_time,\n			pre_salesorder.quantity AS pre_num,\n			now_salesorder.quantity AS now_num\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (NOW())\n						ELSE\n							YEAR (NOW())\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (date)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time\n				FROM\n					tmp_date a\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				now_s_detail.id AS salesorderid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (ld_salesorder.signed_data)\n					ELSE\n						YEAR (ld_salesorder.signed_data)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					ELSE\n						MONTH (ld_salesorder.signed_data)\n					END\n				) AS group_time,\n				sum(now_s_detail.tax_amount) AS tax_amount,\n				sum(now_s_detail.quantity) AS quantity\n			FROM\n				ld_salesorder\n			LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_salesorder.signed_data BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS salesorderid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					ELSE\n						MONTH (ld_salesorder.signed_data)\n					END\n				) AS group_time,\n				sum(pre_s_detail.tax_amount) AS tax_amount,\n				sum(pre_s_detail.quantity) AS quantity\n			FROM\n				ld_salesorder\n			LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time', 'Default', NULL, NULL, 'product_salesorders_quantity_y_to_y');
