end ||
delimiter;

call insertinto_customreport_sqlchart();
delimiter;

call AddColumn('ld_approve','sequence','int','4','');
delimiter;
set @i = 0;
update ld_approve set sequence = @i:=@i+1 ORDER BY sequence,id;
delimiter;

call AddColumn('ld_automaticreminds','sequence','int','4','');
delimiter;
set @i = 0;
update ld_automaticreminds set sequence = @i:=@i+1 ORDER BY sequence,id;
delimiter;

call AddColumn('ld_templateprint','sequence','int','4','');
delimiter;
set @i = 0;
update ld_templateprint set sequence = @i:=@i+1 ORDER BY sequence,templateprintid;
delimiter;

call AddColumn('ld_documenttemplates','sequence','int','4','');
delimiter;
set @i = 0;
update ld_documenttemplates set sequence = @i:=@i+1 ORDER BY sequence,templateid;
delimiter;

call AddColumn('ld_template_calendar','sequence','int','4','');
delimiter;
set @i = 0;
update ld_template_calendar set sequence = @i:=@i+1 ORDER BY sequence,templateid;
delimiter;

update ld_stuff set datarangmodule='SalesOrder,ServiceContracts,PaymentPlan,PurchaseOrder,SendCashBill,SendPayment' where stufftitle='RECEIVESUMMARY';
delimiter;

call addtableIndex('ld_contactrecords','idx_contactrecord_accountid','accountid');
delimiter;

SET @labelbol = 'APPROVALNOTEMPTY';
INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
SELECT 'zh',@labelbol,'审批流程不能为空','jspop' FROM DUAL 
WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'zh' AND labelbol=@labelbol and Labeltype='jspop');
INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
SELECT 'en',@labelbol,'Approval process can not be empty','jspop' FROM DUAL 
WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'en' AND labelbol=@labelbol and Labeltype='jspop');
delimiter;

insert into ld_desk(languagetype,labelbol,fieldlabel,labeltype)
select 'zh','RELATEDEXPORT','详情页导出','fixedstr' from dual
where not exists(select 1 from ld_desk where languagetype='zh' and labelbol='RELATEDEXPORT' and labeltype='fixedstr');
insert into ld_desk(languagetype,labelbol,fieldlabel,labeltype)
select 'en','RELATEDEXPORT',"Related Export",'fixedstr' from dual
where not exists(select 1 from ld_desk where languagetype='en' and labelbol='RELATEDEXPORT' and labeltype='fixedstr');
delimiter;

SET @module='SocialPromotion';
SET @tabid=(SELECT tabid FROM ld_tab WHERE `name`=@module);
update ld_relatedlists set actions='select,export' where name='get_SocialPromotionForm' and tabid=@tabid;

SET @actionname='ExportRelated';
SET @actionlabel='RELATEDEXPORT';
SET @MAX_actionid=IFNULL((SELECT MAX(actionid) FROM ld_actionmapping),0);
INSERT INTO ld_actionmapping(actionid,actionname,securitycheck,actionlabel)
SELECT @MAX_actionid+1,@actionname,0,@actionlabel FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ld_actionmapping WHERE actionname = 'ExportRelated' AND actionlabel='RELATEDEXPORT');

SET @actionid=(SELECT actionid FROM ld_actionmapping where actionname = 'ExportRelated' AND actionlabel='RELATEDEXPORT');
SET @MAX_seq=IFNULL((SELECT MAX(sequence) FROM ld_profileallpermission where tabid=@tabid),0);
INSERT INTO ld_profileallpermission(tabid,operation,sequence)
SELECT @tabid,@actionid,@MAX_seq+1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ld_profileallpermission WHERE tabid =@tabid AND operation=@actionid);
delimiter;

UPDATE ld_field SET autowordwrap = 'yes' WHERE (bigtype = 'richtext');
delimiter;

CALl AddColumn('ld_customtable_module','pathtype','VARCHAR','100','');
delimiter;
update ld_customtable_module set pathtype='mainmodule' where parent_id=0 and ifnull(pathtype,'')='';
update ld_customtable_module set pathtype='next' where parent_id>0 and ifnull(pathtype,'')='';
delimiter;

UPDATE ld_desk SET fieldlabel='自动定位' WHERE labelbol='AUTOMATICCHECKIN' and Labeltype='fixedstr' and languagetype='zh';
UPDATE ld_desk SET fieldlabel='Automatic positioning' WHERE labelbol='AUTOMATICCHECKIN' and Labeltype='fixedstr' and languagetype='en';
delimiter;
UPDATE ld_desk SET fieldlabel='自动定位' WHERE labelbol='automaticsignin' and Labeltype='fixedstr' and languagetype='zh';
UPDATE ld_desk SET fieldlabel='Automatic positioning' WHERE labelbol='automaticsignin' and Labeltype='fixedstr' and languagetype='en';
delimiter;

update ld_workreport_field set related_time = 'thisweek',related_fieldid = 1 where name='worksummary' and type=2 and id=4;
delimiter;
-- 2023-11-29

-- SET GLOBAL log_bin_trust_function_creators = 1;
DROP FUNCTION IF EXISTS `ldcrm_digitformat`;
delimiter ||
CREATE FUNCTION `ldcrm_digitformat`(
	in_num DECIMAL(25,8),
	in_type VARCHAR(100)
) RETURNS mediumtext CHARSET GBK
BEGIN

	SET @digit_length=IFNULL((
		SELECT 
			deploy_value 
		FROM ld_systems_deploy 
		WHERE (
			CASE 
				WHEN in_type='数量' THEN deploy_type=49
				WHEN in_type='单价' THEN deploy_type=93
				WHEN in_type='金额' THEN deploy_type=351
			END)
		),2);

	IF @digit_length=0 THEN
		RETURN(ROUND(in_num,0));

	ELSEIF @digit_length=1 THEN
		RETURN(ROUND(in_num,1));

	ELSEIF @digit_length=2 THEN
		RETURN(ROUND(in_num,2));

	ELSEIF @digit_length=3 THEN
		RETURN(ROUND(in_num,3));

	ELSEIF @digit_length=4 THEN
		RETURN(ROUND(in_num,4));

	ELSEIF @digit_length=5 THEN
		RETURN(ROUND(in_num,5));

	ELSEIF @digit_length=6 THEN
		RETURN(ROUND(in_num,6));

	ELSEIF @digit_length=7 THEN
		RETURN(ROUND(in_num,7));

	ELSEIF @digit_length=8 THEN
		RETURN(ROUND(in_num,8));

	ELSE
		RETURN(ROUND(in_num,2));
	END IF;

end ||
delimiter;


