create PROCEDURE update_customreport_sqlchart()
begin
IF NOT  EXISTS(SELECT * from ld_report_analysis_folder WHERE `name` = 'YoY_MoM') then
SELECT max(analysisfolder_id) INTO @folderid from ld_report_analysis_folder;
SELECT analysisfolder_id INTO @parent_id from ld_report_analysis_folder WHERE `name` = 'CustomEcharts';
INSERT INTO `ld_report_analysis_folder` (`analysisfolder_id`, `name`, `folderlabel_zh`, `folderlabel_en`, `parent_id`, `description`, `smcreatorid`, `createdtime`, `sequence`, `visible`, `systemdefault`, `version`, `modify_id`, `modify_time`, `deleted`, `allocatetype`, `depth`, `approveallocatetype`, `primaryname`) VALUES (@folderid + 1, 'YoY_MoM', '同比环比分析', 'YoY and MoM', @parent_id, '', '1', '2022-11-29 11:53:24', '4', 'yes', 'yes', '', '1', '2022-11-29 11:53:24', '0', '0', '2', '0', NULL);
UPDATE ld_customreport set analysisfolder_id = (@folderid + 1) WHERE primaryname LIKE '%_y_to_y' OR primaryname LIKE '%_m_to_m';
END IF;
end ||
delimiter;

